using UnityEngine;
namespace LWS.TruckSports.Editor {
// Additive native scene migrations; the established authors retain ownership of sport configuration.
public static class SportsProductionAuthoring {
 public static void InstallScene(){var tug=Object.FindAnyObjectByType<LWS.TruckTugOfWar.TugMatch>();if(tug!=null)LWS.TruckTugOfWar.Editor.TugProductionAuthoring.Install(tug);var swing=Object.FindAnyObjectByType<LWS.TruckGiantSwing.SwingMatch>();if(swing!=null)LWS.TruckGiantSwing.Editor.SwingProductionAuthoring.Install(swing);var wall=Object.FindAnyObjectByType<LWS.TruckWallball.WallballMatch>();if(wall!=null)LWS.TruckWallball.Editor.WallballProductionAuthoring.Install(wall);var buz=Object.FindAnyObjectByType<LWS.TruckBuzkashi.BuzMatch>();if(buz!=null)LWS.TruckBuzkashi.Editor.BuzProductionAuthoring.Install(buz);var wife=Object.FindAnyObjectByType<LWS.TruckWifeCarrying.WifeMatch>();if(wife!=null)LWS.TruckWifeCarrying.Editor.WifeProductionAuthoring.Install(wife);var mattress=Object.FindAnyObjectByType<LWS.TruckMattressRacing.MattressMatch>();if(mattress!=null)LWS.TruckMattressRacing.Editor.MattressProductionAuthoring.Install(mattress);MasterRepairs();SportsSnowAuthoring.InstallScene();SportsWaterAuthoring.InstallScene();}
 public static void MasterRepairs(){var terrier=Object.FindAnyObjectByType<LWS.TruckTerrierRacing.TerrierMatch>();if(terrier!=null){if(terrier.dessert==null||terrier.dessert.winnerGate==null)LWS.TruckTerrierRacing.Editor.TerrierDessertAuthoring.Install(terrier);var finishPosition=terrier.course.finish.localPosition;finishPosition.z=terrier.course.Length;terrier.course.finish.localPosition=finishPosition;terrier.course.UpdateGeometry();UnityEditor.EditorUtility.SetDirty(terrier.course.groundMesh.sharedMesh);terrier.dessert.Align();LWS.TruckTerrierRacing.Editor.TerrierVolcanoAuthoring.Install(terrier);}var curling=Object.FindAnyObjectByType<LWS.TruckCurling.CurlingMatch>();if(curling!=null)LWS.TruckCurling.Editor.CurlingRepairAuthoring.Install(curling);var cheese=Object.FindAnyObjectByType<LWS.TruckCheeseRolling.CheeseMatch>();if(cheese!=null)LWS.TruckCheeseRolling.Editor.CheeseRepairAuthoring.Install(cheese);var keep=Object.FindAnyObjectByType<LWS.TruckKeepaway.KeepawayMatch>();if(keep!=null)LWS.TruckKeepaway.Editor.KeepawayRepairAuthoring.Install(keep);var poker=Object.FindAnyObjectByType<LWS.TruckPoker.PokerMatch>();if(poker!=null)LWS.TruckPoker.Editor.PokerRepairAuthoring.Install(poker);var bungee=Object.FindAnyObjectByType<LWS.TruckBungeeDemolition.BungeeMatch>();if(bungee!=null)LWS.TruckBungeeDemolition.Editor.BungeeExpansionAuthoring.Install(bungee);var mattress=Object.FindAnyObjectByType<LWS.TruckMattressRacing.MattressMatch>();if(mattress!=null){LWS.TruckMattressRacing.Editor.MattressPillowAuthoring.Install(mattress);foreach(var obstacle in mattress.world.obstacles)if(obstacle.kind==LWS.TruckMattressRacing.MattressObstacleKind.Sheep)SheepMotionAuthoring.Install(obstacle.gameObject,obstacle.transform);}RefreshHelp();}
 static void RefreshHelp(){var session=Object.FindAnyObjectByType<SportsEventSession>();if(session==null||session.menus==null||session.menus.pages.Length<=4||session.menus.pages[4]==null)return;foreach(var text in session.menus.pages[4].GetComponentsInChildren<TMPro.TMP_Text>(true))if(text.name=="Rules and controls"){text.text=session.Help;UnityEditor.EditorUtility.SetDirty(text);}}
}}